use std::io::Read;

fn fail() -> ! {
    println!("error");
    std::process::exit(1);
}

fn main() {
    let mut s = String::new();
    if std::io::stdin().read_to_string(&mut s).is_err() {
        fail();
    }
    let mut lines = s.lines();
    let first: Vec<&str> = match lines.next() {
        Some(l) => l.split_whitespace().collect(),
        None => fail(),
    };
    if first.len() != 2 {
        fail();
    }
    let r: usize = first[0].parse().unwrap_or_else(|_| fail());
    let c: usize = first[1].parse().unwrap_or_else(|_| fail());
    if r < 1 || c < 1 || r > 20 || c > 20 {
        fail();
    }
    let mut m: Vec<Vec<i64>> = Vec::new();
    for _ in 0..r {
        let l = match lines.next() {
            Some(l) => l,
            None => fail(),
        };
        let row: Vec<i64> = l
            .split_whitespace()
            .map(|t| t.parse().unwrap_or_else(|_| fail()))
            .collect();
        if row.len() != c {
            fail();
        }
        m.push(row);
    }
    let (mut top, mut bot, mut left, mut right) = (0i32, r as i32 - 1, 0i32, c as i32 - 1);
    let mut out: Vec<String> = Vec::new();
    while top <= bot && left <= right {
        for j in left..=right {
            out.push(m[top as usize][j as usize].to_string());
        }
        top += 1;
        for i in top..=bot {
            out.push(m[i as usize][right as usize].to_string());
        }
        right -= 1;
        if top <= bot {
            for j in (left..=right).rev() {
                out.push(m[bot as usize][j as usize].to_string());
            }
            bot -= 1;
        }
        if left <= right {
            for i in (top..=bot).rev() {
                out.push(m[i as usize][left as usize].to_string());
            }
            left += 1;
        }
    }
    println!("{}", out.join(" "));
}

